import pytest

from inline_snapshot.testing import Example

STORAGE_BACKEND = """\
from contextlib import contextmanager
from hashlib import sha256
from shutil import copyfile

from inline_snapshot.plugin import ExternalLocation, Storage, StorageLookupError


class FileStorage(Storage):
    def __init__(self, directory, name="custom"):
        self.directory = directory
        self.name = name

    @contextmanager
    def load(self, location):
        path = self.directory / location.path
        if not path.exists():
            raise StorageLookupError(f"snapshot {location.path!r} is missing", files=[])
        yield path

    def new_location(self, location, file_path):
        return location.with_stem(location.stem or "value")

    def store(self, location, file_path):
        self.directory.mkdir(parents=True, exist_ok=True)
        copyfile(file_path, self.directory / location.path)

    def delete(self, location):
        (self.directory / location.path).unlink()

    def find_unused_externals(self, used_externals):
        used = {location.path for location in used_externals}
        return [
            ExternalLocation.from_name(f"{self.name}:{path.name}")
            for path in sorted(self.directory.glob("*"))
            if path.name not in used
        ]


class CasefoldStorage(FileStorage):
    def lazy_compare(self, location, other):
        with self.load(location) as path:
            return path.read_text().casefold() == other.value.casefold()


class DigestStorage(FileStorage):
    def lazy_compare(self, location, other):
        return location.stem == sha256(other.data.read_bytes()).hexdigest()

    def new_location(self, location, file_path):
        return location.with_stem(sha256(file_path.read_bytes()).hexdigest())


class OfflineDigestStorage(DigestStorage):
    @contextmanager
    def load(self, location):
        raise OSError("snapshot downloads are unavailable")
        yield


class OfflineCatalogStorage(FileStorage):
    def find_unused_externals(self, used_externals):
        raise OSError("snapshot catalog is unavailable")
"""

EXTERNAL_SOURCES = """\
# this file is generated by inline-snapshot and requires no manual edits (https://15r10nk.github.io/inline-snapshot/latest/external/external/#cleaning-up-old-externals)
tests/test_something.py
"""


@pytest.fixture
def storage_example():
    def create(
        files,
        *,
        backend="FileStorage",
        name="custom",
        plugin=None,
        storage_dir=".inline-snapshot",
    ):
        if plugin is None:
            plugin = f"""\
from inline_snapshot.plugin import hookimpl
from storage_backend import {backend}

@hookimpl
def register_storages(storage_dir):
    return {{"{name}": {backend}(storage_dir / "{name}", "{name}")}}
"""
        return Example(
            {
                "storage_backend.py": STORAGE_BACKEND,
                "conftest.py": plugin,
                f"{storage_dir}/files_using_external.txt": EXTERNAL_SOURCES,
                **files,
            }
        )

    return create
